import type { SortingPayment } from "./merchant.js";
import { associationPurpose, cardVenuePurpose, paymentPurpose } from "./payment-purpose.js";
import { compileShopList, type ShopFound, type ShopListData } from "./shop-matcher.js";
import shopList from "./shops.de.json" with { type: "json" };

export type { ShopFound, StarterRule } from "./shop-matcher.js";
// The built-in shop list: German rules written by hand and brands from OpenStreetMap's name-suggestion-index,
// generated by scripts/build-shop-list.ts (sources, licence and decisions there and in scripts/shop-list.de.ts).
// No people or ambiguous marketplaces/processors.
// JSON imports type tuples as plain arrays; the file is generated in exactly this shape (checked in the tests).
const matcher = compileShopList(shopList as unknown as ShopListData);
export const STARTER_RULES = matcher.rules;

/** Optional towns come from the person's card lines; without them only this payment's own town is known. */
export function starterCategory(payment: SortingPayment, categories: readonly { id: string }[], towns?: readonly string[]): string | null {
  // Find the best matching rule before checking availability: a disabled specific
  // category must not fall through to a misleading broader rule (Uber Eats → Taxi).
  const categoryId = paymentPurpose(payment) ?? matcher.match(payment, towns) ?? cardVenuePurpose(payment) ?? associationPurpose(payment);
  return categoryId !== null && categories.some((c) => c.id === categoryId) ? categoryId : null;
}

/** The built-in list's decision for a payment, with the name that made it (receipts compare shops by it). */
export const findShop = (payment: SortingPayment, towns?: readonly string[]): ShopFound | null => matcher.find(payment, towns);
